{
  "name": "汉密尔顿自动化液体处理工作站",
  "name_en": "Hamilton automated liquid handling workstation",
  "manufacturer": "Hamilton Robotics",
  "description": "汉密尔顿自动化液体处理工作站是一类用于实验室自动化移液、分液和样品制备的台式仪器，常见于高通量实验流程。它通常配备移液通道、机械运动平台以及用于板、管等耗材处理的模块，可用于试剂分装、样品转移和标准化液体处理任务。",
  "description_en": "A Hamilton automated liquid handling workstation is a benchtop laboratory instrument used for automated pipetting, dispensing, and sample preparation in high-throughput workflows. It typically combines pipetting channels, a robotic motion system, and modules for handling plates, tubes, and other labware, and is used for reagent distribution, sample transfer, and standardized liquid handling tasks.",
  "tag_hints": [
    "automated liquid handling",
    "laboratory robotics",
    "high-throughput sample preparation",
    "pipetting automation",
    "plate and tube handling",
    "reagent dispensing"
  ],
  "actions": [
    {
      "action_name": "auto-read",
      "description": "读取工作站返回的数据。",
      "description_en": "Read data returned by the workstation."
    },
    {
      "action_name": "auto-read_exact",
      "description": "精确读取指定字节数的工作站返回数据。",
      "description_en": "Read an exact number of bytes returned by the workstation."
    },
    {
      "action_name": "auto-send_command",
      "description": "向液体处理工作站发送命令并等待响应。",
      "description_en": "Send a command to the liquid handling workstation and wait for the response."
    },
    {
      "action_name": "auto-serialize",
      "description": "导出工作站通信配置。",
      "description_en": "Serialize the workstation communication configuration."
    },
    {
      "action_name": "auto-setup",
      "description": "初始化并连接液体处理工作站。",
      "description_en": "Initialize and connect to the liquid handling workstation."
    },
    {
      "action_name": "auto-stop",
      "description": "停止通信并断开与工作站的连接。",
      "description_en": "Stop communication and disconnect from the workstation."
    },
    {
      "action_name": "auto-write",
      "description": "向工作站写入数据。",
      "description_en": "Write data to the workstation."
    },
    {
      "action_name": "auto-parse_error",
      "description": "解析工作站返回的错误信息。",
      "description_en": "Parse error information returned by the workstation."
    },
    {
      "action_name": "auto-is_connected",
      "description": "获取连接状态。",
      "description_en": "Get connection status."
    }
  ]
}

